import React, { useState } from 'react'

const REPLICATE_TOKEN = 'PASTE_YOUR_TOKEN_HERE' // ⚠️ front-end only for quick testing!

function AIReimager({ site, onClose }) {
  const [prompt, setPrompt] = useState('')
  const [generating, setGenerating] = useState(false)
  const [generatedImage, setGeneratedImage] = useState(null)
  const [error, setError] = useState(null)

  const handleGenerate = async () => {
    setGenerating(true)
    setGeneratedImage(null)
    setError(null)

    try {
      // 1) Kick off prediction
      const startRes = await fetch('https://api.replicate.com/v1/predictions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          // ✅ FIX: needs "Token " prefix
          'Authorization': `r8_ERi31AFN7mIkcIluQTAMH5OQfbVhcBY3HfKpr`,
        },
        body: JSON.stringify({
          // You can keep this version string — Replicate accepts owner/model:version
          version: 'stability-ai/sdxl:39ed52f2a78e934b3ba6e2a89f5b1c712de7dfea535525255b1aa35c5565e08b',
          input: {
            prompt: `${prompt}, architectural visualization, photorealistic, high quality, detailed`,
            negative_prompt: 'blurry, low quality, distorted',
          },
        }),
      })

      if (!startRes.ok) {
        const t = await startRes.text()
        throw new Error(`Replicate start error: ${t}`)
      }

      const prediction = await startRes.json()
      if (!prediction?.id) {
        throw new Error('No prediction id returned')
      }

      // 2) Poll for completion
      let result = prediction
      while (result.status !== 'succeeded' && result.status !== 'failed') {
        await new Promise((r) => setTimeout(r, 1000))
        const pollRes = await fetch(`https://api.replicate.com/v1/predictions/${prediction.id}`, {
          headers: {
            // ✅ FIX: use your token here too
            'Authorization': `Token ${REPLICATE_TOKEN}`,
          },
        })
        if (!pollRes.ok) {
          const t = await pollRes.text()
          throw new Error(`Replicate poll error: ${t}`)
        }
        result = await pollRes.json()
      }

      if (result.status === 'succeeded') {
        // Replicate usually returns an array of image URLs in output
        const out = Array.isArray(result.output) ? result.output[0] : result.output
        if (!out) throw new Error('No image URL in output')
        setGeneratedImage(out)
      } else {
        throw new Error('Generation failed')
      }
    } catch (e) {
      console.error(e)
      setError(e.message || 'Error generating image')
      alert('Error generating image: ' + (e.message || e))
    } finally {
      setGenerating(false)
    }
  }

  return (
    <div style={{
      position: 'fixed',
      top: 0, left: 0, right: 0, bottom: 0,
      backgroundColor: 'rgba(0,0,0,0.8)',
      display: 'flex', justifyContent: 'center', alignItems: 'center',
      zIndex: 3000, padding: '20px'
    }}>
      <div style={{
        backgroundColor: 'white', padding: '30px', borderRadius: '12px',
        width: '90%', maxWidth: '800px', maxHeight: '90vh', overflow: 'auto',
        boxShadow: '0 4px 20px rgba(0,0,0,0.3)'
      }}>
        <h2 style={{ marginTop: 0 }}>✨ Reimagine: {site.name}</h2>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px', marginBottom: '20px' }}>
          <div>
            <h3>Original Derelict Site</h3>
            {site.photo_url ? (
              <img
                src={site.photo_url}
                alt={site.name}
                style={{ width: '100%', height: '250px', objectFit: 'cover', borderRadius: '8px', border: '2px solid #ddd' }}
              />
            ) : (
              <div style={{
                width: '100%', height: '250px', backgroundColor: '#f0f0f0',
                display: 'flex', alignItems: 'center', justifyContent: 'center', borderRadius: '8px'
              }}>
                No photo available
              </div>
            )}
          </div>

          <div>
            <h3>AI Reimagined</h3>
            {generatedImage ? (
              <img
                src={generatedImage}
                alt="AI Generated"
                style={{ width: '100%', height: '250px', objectFit: 'cover', borderRadius: '8px', border: '2px solid #4CAF50' }}
              />
            ) : (
              <div style={{
                width: '100%', height: '250px', backgroundColor: '#f0f0f0',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                borderRadius: '8px', color: '#666'
              }}>
                {generating ? '🎨 Generating...' : 'Click generate to see magic'}
              </div>
            )}
          </div>
        </div>

        <div style={{ marginBottom: '20px' }}>
          <label style={{ display: 'block', marginBottom: '10px', fontWeight: 'bold' }}>
            How would you like to reimagine this site?
          </label>
          <textarea
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder="e.g., modern glass office building, renovated luxury apartments, community garden..."
            rows="3"
            style={{ width: '100%', padding: '12px', border: '1px solid #ccc', borderRadius: '6px', fontSize: '16px', fontFamily: 'inherit' }}
          />
        </div>

        <div style={{ display: 'flex', gap: '10px' }}>
          <button
            onClick={handleGenerate}
            disabled={!prompt || generating}
            style={{
              flex: 1, padding: '12px',
              backgroundColor: (!prompt || generating) ? '#ccc' : '#4CAF50',
              color: 'white', border: 'none', borderRadius: '6px', fontSize: '16px', fontWeight: 'bold',
              cursor: (!prompt || generating) ? 'not-allowed' : 'pointer'
            }}
          >
            {generating ? '✨ Generating Magic...' : '🎨 Generate Reimagination'}
          </button>
          <button
            onClick={onClose}
            disabled={generating}
            style={{
              padding: '12px 24px', backgroundColor: '#666', color: 'white',
              border: 'none', borderRadius: '6px', fontSize: '16px', fontWeight: 'bold',
              cursor: generating ? 'not-allowed' : 'pointer'
            }}
          >
            Close
          </button>
        </div>

        {generatedImage && (
          <div style={{ marginTop: '20px', textAlign: 'center' }}>
            {/* ✅ FIX: add the missing <a> tag */}
            <a
              href={generatedImage}
              download="reimagined-site.png"
              style={{
                display: 'inline-block', padding: '10px 20px',
                backgroundColor: '#2196F3', color: 'white', textDecoration: 'none',
                borderRadius: '6px', fontWeight: 'bold'
              }}
            >
              💾 Download Reimagined Image
            </a>
          </div>
        )}

        {error && (
          <p style={{ marginTop: 12, color: '#d32f2f' }}>{error}</p>
        )}
      </div>
    </div>
  )
}

export default AIReimager
